// reproduce-headless-warning.js
// This script uses Lighthouse's V2 report generator to produce a standalone HTML
// that includes the headless-chrome network-throttling warning banner.

const fs = require('fs');
const path = require('path');
const ReportGeneratorV2 = require('lighthouse/report/v2/report-generator.js');

// Load a sample Lighthouse v2 results file
const sampleResults = require('lighthouse/core/test/results/sample_v2.json');

// Inject the headless-Chrome warning into the runtimeWarnings array
sampleResults.runtimeWarnings = [
  'Your site\'s mobile performance may be worse than the numbers presented in this report. ' +
  'Lighthouse could not test on a mobile connection because Headless Chrome does not support ' +
  'network throttling. See crbug.com/728451.'
];

// Generate the HTML report (includes the warning banner)
const reportHtml = new ReportGeneratorV2().generateReportHtml(sampleResults);

// Write out to disk
const outFile = path.join(process.cwd(), 'headless-warning-report.html');
fs.writeFileSync(outFile, reportHtml, 'utf8');
console.log(`✓ Generated report with warning banner: ${outFile}`);
